    for r in cand.get("relations", []):
        t = normalize_relation(r)
        if t[2] in VALID_TYPES:
            rels.add(t)
    return rels


def compute_f1(pred_set, gold_set):
    if not pred_set and not gold_set:
        return 1.0, 1.0, 1.0
    if not pred_set or not gold_set:
        return 0.0, 0.0, 0.0
    tp = len(pred_set & gold_set)
    p = tp / len(pred_set)
    r = tp / len(gold_set)
    f1 = 2 * p * r / (p + r) if (p + r) > 0 else 0.0
    return p, r, f1


def exact_sc_select(candidates):
    n = len(candidates)
