        elif strategy == "exact_sc":
            idx = exact_sc_select(candidates)
            pred_set = candidate_rel_set(candidates[idx])
        elif strategy == "freq_merge":
            k = kwargs.get("k", 2)
            pred_set = frequency_merge(candidates, k)
        elif strategy == "oracle":
            idx = oracle_select(candidates, gold_rels)
            pred_set = candidate_rel_set(candidates[idx])
        elif strategy == "random":
            idx = random.randint(0, len(candidates) - 1)
            pred_set = candidate_rel_set(candidates[idx])
        else:
            pred_set = set()

        tp = len(pred_set & gold_rels)
        total_tp += tp
        total_pred += len(pred_set)
        total_gold += len(gold_rels)

    micro_p = total_tp / max(total_pred, 1)
    micro_r = total_tp / max(total_gold, 1)
    micro_f1 = 2 * micro_p * micro_r / (micro_p + micro_r) if (micro_p + micro_r) > 0 else 0.0
    return {
        "micro_p": round(micro_p, 4),
        "micro_r": round(micro_r, 4),
        "micro_f1": round(micro_f1, 4),
        "total_tp": total_tp,
        "total_pred": total_pred,
        "total_gold": total_gold,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--results_dir", required=True)
    parser.add_argument("--gold_file", required=True)
    parser.add_argument("--output_file", required=True)
    args = parser.parse_args()

    gold = load_gold(args.gold_file)
    total_gold_rels = sum(len(v) for v in gold.values())
    print(f"Loaded {len(gold)} gold docs, {total_gold_rels} total relations")

    all_results = load_results(args.results_dir)
    print(f"Found {len(all_results)} (n, seed) settings")

    n_values = sorted(set(n for n, _ in all_results.keys()))
    final = {}

    for n in n_values:
        seeds = sorted([s for n2, s in all_results.keys() if n2 == n])

        if n == 1:
            strategies = [("greedy", {})]
        else:
            strategies = [
                ("exact_sc", {}),
                ("oracle", {}),
                ("random", {}),
            ]
            for k in range(1, min(n + 1, 17)):
                strategies.append(("freq_merge", {"k": k}))

        for strategy, kwargs in strategies:
            label = strategy
            if strategy == "freq_merge":
                label = f"freq_merge_k{kwargs['k']}"

            seed_results = []
            for seed in seeds:
                key = (n, seed)
                if key not in all_results:
                    continue
                random.seed(seed)
                result = evaluate_strategy(all_results[key], gold, strategy, **kwargs)
                result["seed"] = seed
                seed_results.append(result)

            if seed_results:
                f1s = [r["micro_f1"] for r in seed_results]
                mean_f1 = sum(f1s) / len(f1s)
                std_f1 = (sum((x - mean_f1) ** 2 for x in f1s) / (len(f1s) - 1)) ** 0.5 if len(f1s) > 1 else 0.0

                setting_key = f"n{n}_{label}"
                final[setting_key] = {
                    "n": n, "strategy": label, "seeds": seeds,
                    "mean_micro_f1": round(mean_f1 * 100, 2),
                    "std_micro_f1": round(std_f1 * 100, 2),
                    "mean_micro_p": round(sum(r["micro_p"] for r in seed_results) / len(seed_results) * 100, 2),
                    "mean_micro_r": round(sum(r["micro_r"] for r in seed_results) / len(seed_results) * 100, 2),
                    "per_seed": seed_results,
                }
                print(f"N={n:2d} {label:25s}: F1={mean_f1*100:.2f} +/- {std_f1*100:.2f}")

    # Best freq_merge per N
    best_freq = {}
    for key, val in final.items():
        if "freq_merge" in key:
            n_val = val["n"]
            if n_val not in best_freq or val["mean_micro_f1"] > best_freq[n_val]["mean_micro_f1"]:
                best_freq[n_val] = val

    # Parse stats
    parse_summary = {}
    parse_by_n = defaultdict(list)
    for pf in sorted(Path(args.results_dir).glob("parse_stats_re_*.json")):
        with open(pf) as f:
            ps = json.load(f)
            parse_by_n[ps["n_candidates"]].append(ps)
    for n_val in sorted(parse_by_n.keys()):
        total = sum(ps["total_parses"] for ps in parse_by_n[n_val])
        success = sum(ps["successful_parses"] for ps in parse_by_n[n_val])
        rate = success / max(total, 1)
        parse_summary[f"n{n_val}"] = {"total": total, "success": success, "rate_pct": round(rate * 100, 2)}
        print(f"Parse N={n_val}: {rate*100:.1f}% ({success}/{total})")

    greedy_f1 = final.get("n1_greedy", {}).get("mean_micro_f1", 0.0)

    print(f"\n{'='*60}")
    print(f"Greedy F1: {greedy_f1:.2f}")
    for n_val in sorted(best_freq.keys()):
        bf = best_freq[n_val]
        print(f"Best freq_merge N={n_val}: {bf['strategy']}, F1={bf['mean_micro_f1']:.2f}+/-{bf['std_micro_f1']:.2f}")

    for n_val in n_values:
        oracle_key = f"n{n_val}_oracle"
        if oracle_key in final:
            gap = final[oracle_key]["mean_micro_f1"] - greedy_f1
            print(f"Oracle gap N={n_val}: {gap:+.2f}pt")

    pass_result = False
    for n_val in n_values:
        if n_val < 8:
            continue
        for key, val in final.items():
            if val["n"] == n_val and val["strategy"] not in ("oracle", "random", "greedy"):
                if val["mean_micro_f1"] >= greedy_f1 + 1.0:
                    pass_result = True
                    break
        if pass_result:
            break
    print(f"\nPass: aggregation@N>=8 > greedy >= 1.0pt? {'YES' if pass_result else 'NO'}")

    output = {
        "results": final,
        "best_freq_merge": {str(k): v for k, v in best_freq.items()},
        "parse_stats": parse_summary,
        "greedy_f1": greedy_f1,
        "pass_result": pass_result,
        "num_gold_docs": len(gold),
        "total_gold_relations": total_gold_rels,
    }
    out_path = Path(args.output_file)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved to {out_path}")


if __name__ == "__main__":
    main()
